func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agent-templates", wrapper.ListAgentTemplates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents", wrapper.ListAgents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents", wrapper.HireAgent)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/agents/{agent_name}", wrapper.RetireAgent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents/{agent_name}", wrapper.GetAgent)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/agents/{agent_name}", wrapper.UpdateAgent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents/{agent_name}/chat", wrapper.ListChatMessages)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{agent_name}/chat", wrapper.SendChatMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents/{agent_name}/chat/stream", wrapper.StreamChat)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents/{agent_name}/one-line", wrapper.GetAgentOneLine)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/agents/{agent_name}/one-line", wrapper.SetAgentOneLine)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents/{agent_name}/output", wrapper.StreamAgentOutput)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{agent_name}/sleep", wrapper.SleepAgent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{agent_name}/tokens", wrapper.IssueAgentToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{agent_name}/wake", wrapper.WakeAgent)

	return m
}

